theorem shakeStrongAdvantage_pure_le_securityBound_of_weakKeyMass_eq_zero
    (hb : CanonicalAddressBounds vp.params) (hn16 : 16 ≤ vp.params.n) (hn : vp.params.n ≤ 32)
    (hnm : vp.params.n ≤ vp.params.m) {pkSeed : (shakeCore vp).PkSeed}
    (hs : weakKeyMass vp pkSeed = 0)
    (adv : StrongUnforgeableAdversary (shakeRomScheme vp optRand (pure pkSeed))) {qh qs : ℕ}
    (hadv : adv.RomQueryBound qh qs) : shakeStrongAdvantage vp adv ≤ byteBound vp qh qs

theorem shakeStrongAdvantage_pure_le_securityBound_of_n_eq_32
    (hb : CanonicalAddressBounds vp.params) (hn : vp.params.n = 32)
    (hnm : vp.params.n ≤ vp.params.m) {pkSeed : (shakeCore vp).PkSeed}
    (hs : ¬IsHonestKey vp (shakeCore vp) (adrsKeyOfList vp (Vector.toList (pkSeed : Bytes _))))
    (adv : StrongUnforgeableAdversary (shakeRomScheme vp optRand (pure pkSeed))) {qh qs : ℕ}
    (hadv : adv.RomQueryBound qh qs) : shakeStrongAdvantage vp adv ≤ byteBound vp qh qs

theorem shakeAdvantage_le_shakeStrongAdvantage
    {optRand : PublicKeyCore (shakeCore vp) → ProbComp (shakeCore vp).Y}
    {pkSeedDist : ProbComp (shakeCore vp).PkSeed}
    (adv : UnforgeableAdversary (shakeRomScheme vp optRand pkSeedDist)) :
    shakeAdvantage vp adv ≤ shakeStrongAdvantage vp
      (⟨adv.main⟩ : StrongUnforgeableAdversary (shakeRomScheme vp optRand pkSeedDist))

theorem unforgeableAdvantage_romScheme_le {e : core.SkSeed ≃ core.Y}
    {optRand : PublicKeyCore core → ProbComp core.Y} {c r : ℕ}
    (h : SecurityTarget core e optRand c r) (pkSeedDist : ProbComp core.PkSeed)
    (adv : UnforgeableAdversary (romScheme core e optRand pkSeedDist)) {qh qs : ℕ}
    (hb : adv.RomQueryBound qh qs) :
    unforgeableAdvantage (ProbCompRuntime.rom (hashSpec core)) adv ≤
      securityBound vp.params (Nat.card core.Y) c r qh qs

theorem romQueryBound_wireReduce (ctx : PureContext)
    {optRand : PublicKeyCore (shakeCore vp) → ProbComp (shakeCore vp).Y}
    {pkSeedDist : ProbComp (shakeCore vp).PkSeed}
    (adv : StrongUnforgeableAdversary (wireShakeScheme vp ctx optRand pkSeedDist))
    {qh qs : ℕ} (hadv : adv.RomQueryBound qh qs) :
    (wireReduce vp ctx adv).RomQueryBound qh qs

theorem wireStrongAdvantage_le (ctx : PureContext)
    {optRand : PublicKeyCore (shakeCore vp) → ProbComp (shakeCore vp).Y}
    {pkSeedDist : ProbComp (shakeCore vp).PkSeed}
    (adv : StrongUnforgeableAdversary (wireShakeScheme vp ctx optRand pkSeedDist)) :
    strongUnforgeableAdvantage (shakeRuntime vp) adv ≤
      shakeStrongAdvantage vp (wireReduce vp ctx adv)
